pub type PAdicTokenizer {
  PAdicTokenizer(base: Int, levels: Int, buffer: BitArray, cache: List(#(String, List(Int))))
}

pub fn new_p_adic_tokenizer(base: Int, levels: Int) -> PAdicTokenizer {
  PAdicTokenizer(base, levels, <<0:size(8192*8)>>, [])
}

pub fn normalize_utf8(input: String) -> String {
  input
  |> string.to_graphemes
  |> list.map(fn(grapheme) {
    case grapheme {
      "á" -> "a"
      "é" -> "e"
      "í" -> "i"
      "ó" -> "o"
      "ú" -> "u"
      "ö" -> "o"
      "ü" -> "u"
      "ő" -> "o"
      "ű" -> "u"
      _ -> grapheme
    }
  })
  |> string.concat
}

pub fn haar_wavelet_decompose(signal: List(Float), level: Int) -> #(List(Float), List(Float)) {
  case signal {
    [] -> #([], [])
    [x] -> #([x /. 2.0], [x /. 2.0])
    [x, y] -> #([(x +. y) /. 2.0], [(x -. y) /. 2.0])
    xs -> {
      let mid = list.length(xs) / 2
      let left = list.take(xs, mid)
      let right = list.drop(xs, mid)
      let #(low_left, high_left) = haar_wavelet_decompose(left, level - 1)
      let #(low_right, high_right) = haar_wavelet_decompose(right, level - 1)
      #(list.append(low_left, low_right), list.append(high_left, high_right))
    }
  }
}

pub fn walsh_hadamard_transform(input: BitArray, dim: Int) -> BitArray {
  case dim {
    1 -> input
    n -> {
      let half = n / 2
      let even = bit_array.slice(input, 0, half * 8) |> result.unwrap(<<>>)
      let odd = bit_array.slice(input, half * 8, half * 8) |> result.unwrap(<<>>)
      let even_t = walsh_hadamard_transform(even, half)
      let odd_t = walsh_hadamard_transform(odd, half)
      let plus = bit_array.concat([even_t, odd_t])
      let minus = bit_array.concat([even_t, bit_array.bitwise_exclusive_or(odd_t, even_t)])
      bit_array.concat([plus, minus])
    }
  }
}

pub fn bitplane_slice(data: BitArray, planes: Int) -> List(BitArray) {
  list.range(0, planes - 1)
  |> list.map(fn(plane) {
    let len = bit_array.byte_size(data) * 8
    list.range(0, len - 1)
    |> list.fold(<<>>, fn(acc, i) {
      let bit = bit_array.slice(data, i, 1) |> result.unwrap(<<0>>) |> bit_array.to_int |> result.unwrap |> fn(b) { b >> plane & 1 }
      bit_array.append(acc, <<bit>>)
    })
  })
}

pub fn p_adic_pad(input: List(Int), target_len: Int, base: Int) -> List(Int) {
  let current_len = list.length(input)
  case current_len >= target_len {
    True -> input
    False -> {
      let pad_len = target_len - current_len
      let pad_value = list.repeat(0, pad_len)
      list.append(input, pad_value)
    }
  }
}

pub fn polyphase_decompose(input: List(Int), phases: Int, base: Int) -> List(List(Int)) {
  list.range(0, phases - 1)
  |> list.map(fn(phase) {
    input
    |> list.indexed
    |> list.filter(fn(pair) { let #(idx, _) = pair idx % phases == phase })
    |> list.map(fn(pair) { let #(_, val) = pair val })
  })
}

pub fn tokenize_batch(inputs: List(String), tokenizer: PAdicTokenizer) -> List(List(Int)) {
  inputs
  |> list.map(fn(input) {
    let normalized = normalize_utf8(input)
    let graphemes = string.to_graphemes(normalized)
    let codes = graphemes
    |> list.map(string.byte_size)
    |> list.map(fn(len) { len % tokenizer.base })
    let #(low, high) = haar_wavelet_decompose(list.map(codes, int.to_float), tokenizer.levels)
    let wavelet = high
    |> list.map(fn(v) { float.round(v) % tokenizer.base })
    let bitplanes = bitplane_slice(bit_array.from_bytes(list.map(wavelet, int.to_bytes(4, Big))), 8)
    let poly = polyphase_decompose(bit_array.to_int_list(bitplanes |> list.first |> result.unwrap(<<>>)), 128, tokenizer.base)
    p_adic_pad(poly |> list.first |> result.unwrap([]), 131072, tokenizer.base)
  })
}

pub fn detokenize_batch(tokens: List(List(Int)), tokenizer: PAdicTokenizer) -> List(String) {
  tokens
  |> list.map(fn(token_list) {
    let phases = list.range(0, 127)
    let reconstructed = phases
    |> list.map(fn(phase) { list.indexed(token_list) |> list.filter(fn(pair) { let #(idx, _) = pair idx % 128 == phase }) |> list.map(fn(pair) { let #(_, val) = pair val }) })
    |> list.flatten
    let bitplanes = list.range(0, 7)
    |> list.map(fn(p) { bit_array.from_int_list(reconstructed) |> fn(ba) { bit_array.map_bits(ba, fn(b, i) { (b >> p) & 1 }) } })
    let wavelet_inv = walsh_hadamard_transform(bitplanes |> list.first |> result.unwrap(<<>>), 131072)
    let #(inv_haar, _) = haar_wavelet_decompose(bit_array.to_float_list(wavelet_inv), tokenizer.levels)
    let chars = inv_haar
    |> list.map(fn(val) { float.round(val) |> char.from_int |> result.unwrap_or('?') })
    string.from_chars(chars)
  })
}

pub fn cache_tokenize(tokenizer: PAdicTokenizer, input: String) -> PAdicTokenizer {
  case list.key_find(tokenizer.cache, input) {
    Ok(tokens) -> tokenizer
    Error(Nil) -> {
      let tokens = tokenize_batch([input], tokenizer) |> list.first |> result.unwrap([])
      let new_cache = list.prepend(tokenizer.cache, #(input, tokens)) |> list.take(1024)
      PAdicTokenizer(..tokenizer, cache: new_cache)
    }
  }
}

pub fn batch_size() -> Int {
  2048
}

pub fn max_context() -> Int {
  131072
}

pub fn base_default() -> Int {
  5
}

pub fn levels_default() -> Int {
  12
}

pub type TokenId = Int

pub fn encode_char(c: Char, base: Int) -> TokenId {
  char.to_int(c) % base
}

pub fn decode_char(id: TokenId, base: Int) -> Char {
  char.from_int(id % 256) |> result.unwrap_or('?')
}

pub fn validate_tokens(tokens: List(TokenId), base: Int) -> Bool {
  tokens
  |> list.all(fn(t) { t >= 0 && t < base })
}

pub fn pad_tokens(tokens: List(TokenId), len: Int) -> List(TokenId) {
  case list.length(tokens) < len {
    True -> list.append(tokens, list.repeat(0, len - list.length(tokens)))
    False -> list.take(tokens, len)
  }
}

pub fn unpad_tokens(tokens: List(TokenId)) -> List(TokenId) {
  tokens
  |> list.reverse
  |> list.drop_while(fn(t) { t == 0 })
  |> list.reverse
}

pub fn serialize_tokens(tokens: List(TokenId)) -> BitArray {
  tokens |> list.fold(<<>>, fn(acc, t) { bit_array.append(acc, <<t:32>>) })
}

pub fn deserialize_tokens(data: BitArray) -> List(TokenId) {
  let len = bit_array.byte_size(data) / 4
  list.range(0, len - 1)
  |> list.map(fn(i) { bit_array.slice(data, i * 4, 4) |> result.unwrap(<<0>>) |> bit_array.to_int |> result.unwrap })
}

pub fn hash_token_stream(tokens: List(TokenId)) -> Int {
  tokens
  |> list.fold(0, fn(acc, t) { (acc * 31 + t) % 2147483647 })
}

pub fn diff_tokens(a: List(TokenId), b: List(TokenId)) -> List(TokenId) {
  list.zip(a, b)
  |> list.map(fn(pair) {
    let #(x, y) = pair
    (x - y + 1000) % 1000
  })
}

pub fn merge_tokens(a: List(TokenId), b: List(TokenId)) -> List(TokenId) {
  list.zip(a, b)
  |> list.map(fn(pair) {
    let #(x, y) = pair
    (x + y) / 2
  })
}

pub fn split_tokens(tokens: List(TokenId), parts: Int) -> List(List(TokenId)) {
  let len = list.length(tokens) / parts
  list.range(0, parts - 1)
  |> list.map(fn(i) { list.drop(tokens, i * len) |> list.take(len) })
}

pub fn join_tokens(parts: List(List(TokenId))) -> List(TokenId) {
  list.flatten(parts)
}

pub fn quantize_tokens(tokens: List(TokenId), bits: Int) -> List(TokenId) {
  tokens
  |> list.map(fn(t) { t >> (8 - bits) })
}

pub fn dequantize_tokens(tokens: List(TokenId), bits: Int) -> List(TokenId) {
  tokens
  |> list.map(fn(t) { t << (8 - bits) })
}

pub fn compress_tokens(tokens: List(TokenId)) -> List(TokenId) {
  let unique = list.unique(tokens) |> list.sort
  tokens
  |> list.map(fn(t) { list.index_of(unique, t) |> result.unwrap(0) })
}

pub fn decompress_tokens(compressed: List(TokenId), unique: List(TokenId)) -> List(TokenId) {
  compressed
  |> list.map(fn(idx) { list.at(unique, idx) |> result.unwrap(0) })
}

pub fn error_correct_tokens(tokens: List(TokenId), threshold: Int) -> List(TokenId) {
  tokens
  |> list.map(fn(t) {
    case t < 0 || t > threshold {
      True -> 0
      False -> t
    }
  })
}

pub fn validate_batch(batch: List(List(TokenId))) -> Bool {
  batch
  |> list.all(fn(tokens) { validate_tokens(tokens, 5) })
}

pub fn batch_pad(batch: List(List(TokenId)), max_len: Int) -> List(List(TokenId)) {
  batch
  |> list.map(fn(tokens) { pad_tokens(tokens, max_len) })
}

pub fn process_stream(input_stream: List(String), tokenizer: PAdicTokenizer) -> #(PAdicTokenizer, List(List(TokenId))) {
  let updated = input_stream
  |> list.fold(tokenizer, fn(acc, inp) { cache_tokenize(acc, inp) })
  let tokens = input_stream
  |> list.map(fn(inp) { list.key_find(updated.cache, inp) |> result.unwrap([]) })
  #(updated, tokens)
}

pub fn stream_detokenize(token_stream: List(List(TokenId)), tokenizer: PAdicTokenizer) -> List(String) {
  detokenize_batch(token_stream, tokenizer)
}

pub fn benchmark_tokenize(inputs: List(String), tokenizer: PAdicTokenizer) -> Float {
  let start = erlang.system_time(Nanosecond)
  let _ = tokenize_batch(inputs, tokenizer)
  let end = erlang.system_time(Nanosecond)
  int.to_float(end - start) /. 1000000.0
}

pub fn benchmark_detokenize(tokens: List(List(TokenId)), tokenizer: PAdicTokenizer) -> Float {
  let start = erlang.system_time(Nanosecond)
  let _ = detokenize_batch(tokens, tokenizer)
  let end = erlang.system_time(Nanosecond)
  int.to_float(end - start) /. 1000000.0
}

pub fn export_cache(tokenizer: PAdicTokenizer, path: String) -> Nil {
  let data = tokenizer.cache |> list.map(fn(pair) { let #(k, v) = pair (k, v) }) |> erlang.term_to_binary
  file.write(path, data) |> result.discard
  nil
}

pub fn import_cache(path: String) -> PAdicTokenizer {
  file.read(path) |> result.unwrap(<<>>) |> erlang.binary_to_term |> fn(t) { list.map(t, fn(p) { let #(k, v) = p #(k, v) }) } |> fn(c) { PAdicTokenizer(base_default(), levels_default(), <<0:size(8192*8)>>, c) }
}

