  detokenize_batch(token_stream, tokenizer)
}

pub fn benchmark_tokenize(inputs: List(String), tokenizer: PAdicTokenizer) -> Float {
  let start = erlang.system_time(Nanosecond)
  let _ = tokenize_batch(inputs, tokenizer)
  let end = erlang.system_time(Nanosecond)
  int.to_float(end - start) /. 1000000.0
}

pub fn benchmark_detokenize(tokens: List(List(TokenId)), tokenizer: PAdicTokenizer) -> Float {
  let start = erlang.system_time(Nanosecond)
  let _ = detokenize_batch(tokens, tokenizer)
  let end = erlang.system_time(Nanosecond)
  int.to_float(end - start) /. 1000000.0
}

pub fn export_cache(tokenizer: PAdicTokenizer, path: String) -> Nil {
  let data = tokenizer.cache |> list.map(fn(pair) { let #(k, v) = pair (k, v) }) |> erlang.term_to_binary
  file.write(path, data) |> result.discard
  nil
}

pub fn import_cache(path: String) -> PAdicTokenizer {
  file.read(path) |> result.unwrap(<<>>) |> erlang.binary_to_term |> fn(t) { list.map(t, fn(p) { let #(k, v) = p #(k, v) }) } |> fn(c) { PAdicTokenizer(base_default(), levels_default(), <<0:size(8192*8)>>, c) }
}
